function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Each menu category is a section with the user‑items‑list class
  $('#sections > section.user-items-list-section').each((_, sec) => {
    const $sec = $(sec);

    // Section heading (e.g., "PLANTEBASERT")
    const $title = $sec.find('.list-section-title p strong');
    const section = $title.length ? cleanText($title.text()) : null;

    // Individual menu items inside the list
    $sec.find('.list-item').each((_, li) => {
      const $li = $(li);

      // Dish name
      const $nameEl = $li.find('.list-item-content__title');
      if (!$nameEl.length) return;
      const name = cleanText($nameEl.text());
      if (!name) return;

      // Description (may span multiple <p>)
      const $descWrapper = $li.find('.list-item-content__description');
      let description = null;
      if ($descWrapper.length) {
        description = cleanText($descWrapper.text());
      }

      // Price – the <strong> inside the description block
      let priceNum = null;
      const $priceEl = $descWrapper.find('strong');
      if ($priceEl.length) {
        priceNum = parsePrice($priceEl.text());
      }

      // Deduplicate identical entries (mobile/desktop duplicates)
      const key = `${section ?? ''}|${name}|${description ?? ''}|${priceNum ?? ''}`;
      if (!seen.has(key)) {
        seen.add(key);
        items.push({ section, name, description, price: priceNum });
      }
    });
  });

  return items;
}
